goal_min=3
goal_max=3
min_quality=15
max_cost=18
unique_field='owner'
result=[]
owners=[]
from itertools import combinations
for combo in combinations(options,3):
  ids=[opt['id'] for opt in combo]
  owners=[]
  unique_ok=True
  for opt in combo:
    if opt['owner'] in owners:
      unique_ok=False
      break
    owners=owners+[opt['owner']]
  if not unique_ok:
    continue
  total_quality=0
  total_cost=0
  for opt in combo:
    total_quality=total_quality+opt['quality']
    total_cost=total_cost+opt['cost']
  if total_quality<min_quality or total_cost>max_cost:
    continue
  requires_ok=True
  selected_ids=[]
  for opt in combo:
    selected_ids=selected_ids+[opt['id']]
  for opt in combo:
    for req in opt['requires']:
      found=False
      for sid in selected_ids:
        if sid==req:
          found=True
          break
      if not found:
        requires_ok=False
        break
    if not requires_ok:
      break
  if requires_ok:
    result=selected_ids
    break
